#!/usr/bin/env python3
"""Regenerate the immutable primary face; run from the worktree root."""
from pathlib import Path

data = Path("vendor/DejaVuSansMono.ttf").read_bytes()
# Formatting only: each escaped byte occupies four source characters, so
# a row of thirty-two bytes occupies a hundred and twenty-eight characters.
row_bytes = 32
with Path("src/font/embedded.h").open("w") as output:
    output.write(
        "/* Generated byte-for-byte from vendor/DejaVuSansMono.ttf.\n"
        " * License: vendor/DejaVu-LICENSE. No runtime path dependency.\n"
        " * Length derives from sizeof font_embedded minus the string terminator. */\n"
        "static const unsigned char font_embedded[] =\n"
    )
    for start in range(0, len(data), row_bytes):
        output.write('"' + "".join(f"\\x{byte:02x}" for byte in data[start:start + row_bytes]) + '"\n')
    output.write(";\n")
